    h,w=len(g),len(g[0])
    out=[row[:] for row in g]
    for i in range(h):
        for j in range(w):
            if g[i][j]:
                c=g[i][j]; y,x=i,j
                while True:
                    y,x=(y+1)%h,(x+1)%w
                    if g[y][x]: break
                    out[y][x]=c
    return out
