    h,w=len(g),len(g[0])
    colors={x for r in g for x in r if x}
    # observed residue->color per period p
    for p in range(1,31):
        m={}; ok=True
        for i in range(h):
            for j in range(w):
                c=g[i][j]
                if c:
                    r=(j-i)%p
                    if m.setdefault(r,c)!=c: ok=False;break
            if not ok:break
        if ok and len(m)==p:  # every diagonal class observed, consistent
            return [[m[(j-i)%p] for j in range(w)] for i in range(h)]
